user-css:
body {

  padding: 50vh 4px 75vh 46px;
  word-break: keep-all;
  text-align: justify;
  box-sizing: border-box;
  text-underline-offset: 3px;


}
/*
body::before {
   content: '';
   position: fixed;
   top: 0;
   left: 0;
   right: 0;
   bottom: 0;
   pointer-events: none; 

z-index: 1;
mask-image: linear-gradient(
    to bottom,
    #000000 0%,
    #000000 30%,
    transparent 35%,
    transparent 45%,
    #000000 50%,
    #000000 100%
  );
  backdrop-filter: blur(0) brightness(45%);
}
*/
body::after {
   position: fixed;
   top: 32vh;
   left: 0;
   right: 0;
   height: 1.5rem;
   content: '';
   background-color: currentColor;
   mix-blend-mode: overlay;
   pointer-events: none;
   box-shadow: currentColor 0 0 10px 5px;
   filter: contrast(2);
}

pre {
  white-space: pre-wrap;
}
pre code {
  background-color: #eff0f1;
  color: #393318;
  font-family: monospace;
  display: block;
  padding: 5px 10px;
  overflow: hidden;
}
blockquote {
  padding: 0;
  padding-inline-start: 2ch;
  border-inline-start: 2px solid var(--bd);
}
aside {
  color: color-mix(in srgb, var(--fg), var(--bg) 20%);
}
body[data-mode="dark"] pre code {
  background-color: #eff0f1;
  color: #393318;
}

/* CSS for sans-serif fonts */
body[data-font=sans-serif] {}
/* CSS for serif fonts */
body[data-font=serif] {}

/* CSS for "sepia" theme */
html[data-mode=sepia] body {}
/* CSS for "light" theme */
html[data-mode=light] body {}
/* CSS for "dark" theme */
html[data-mode=dark] body {}

/* Csutom styling if page includes example.com in the URL */
html[data-page-url*="example.com"] {
  a {
    display: none;
  }
}

strike {
   filter: blur(2.0px) opacity(.35);
   background-color: transparent !important;
   text-decoration: none;
   color: currentColor;
}
strike:hover {

}

b {
   filter: contrast(2.0);

}

mark {
   border-radius: 5px;
}
